"""Starting helper processes with a handover of the caller's objects."""

import os
import subprocess
import sys

from .errors import WSpawnError


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, popen_or_info, inherit):
        if isinstance(popen_or_info, subprocess.Popen):
            self._popen = popen_or_info
            self._process_handle = None
            self.pid = popen_or_info.pid
        else:
            # Native Win32 creation: (process_handle, pid)
            self._popen = None
            self._process_handle, self.pid = popen_or_info
        self.inherit = tuple(inherit)
        self.returncode = None

    def wait(self, timeout=None):
        if self._popen is not None:
            self.returncode = self._popen.wait(timeout=timeout)
            return self.returncode
        # Native Win32 path
        if self.returncode is not None:
            return self.returncode
        from ._winapi import (
            WAIT_OBJECT_0,
            get_exit_code_process,
            wait_for_single_object,
        )
        timeout_ms = 0xFFFFFFFF if timeout is None else int(timeout * 1000)
        wait_for_single_object(self._process_handle, timeout_ms)
        ok, code = get_exit_code_process(self._process_handle)
        if ok and code != 259:  # STILL_ACTIVE = 259
            self.returncode = code
        return self.returncode

    def poll(self):
        if self._popen is not None:
            self.returncode = self._popen.poll()
            return self.returncode
        if self.returncode is not None:
            return self.returncode
        from ._winapi import get_exit_code_process
        ok, code = get_exit_code_process(self._process_handle)
        if ok and code != 259:  # STILL_ACTIVE = 259
            self.returncode = code
            return self.returncode
        return None

    def terminate(self):
        if self._popen is not None:
            self._popen.terminate()
            return
        from ._winapi import terminate_process
        terminate_process(self._process_handle)


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes)):
        raise WSpawnError(
            "argv must be a sequence of arguments, not a single string",
            kind="badarg",
        )
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError(
            "argv must be an iterable of paths: %s" % exc,
            kind="badarg",
        ) from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError(
            "inherit must be a sequence of handles, not a single handle",
            kind="badarg",
        )
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError(
            "inherit must contain integer handles: %s" % exc,
            kind="badarg",
        ) from exc


def _resolve_std_handle(spec):
    """Convert a stdin/stdout/stderr specification to a Windows HANDLE value.

    Accepts:
    - None: use the current standard handle
    - subprocess.DEVNULL: open NUL
    - An integer: treat as a raw handle value
    - A file-like object with a .fileno(): get the underlying OS handle
    """
    if spec is None:
        return None
    if spec is subprocess.DEVNULL:
        return None  # Will be handled specially
    if isinstance(spec, int):
        return spec
    try:
        fd = spec.fileno()
    except (AttributeError, OSError):
        raise WSpawnError(
            "stdin/stdout/stderr must be None, DEVNULL, an int, or a file object",
            kind="badarg",
        )
    if os.name == "nt":
        import msvcrt
        return msvcrt.get_osfhandle(fd)
    return fd


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child process will only be able to access the handles listed in
    ``inherit``, plus any explicitly specified standard streams.  All other
    handles from the parent are invisible to the child.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    if os.name != "nt":
        raise WSpawnError(
            "spawn requires Windows",
            kind="unsupported",
        )

    from ._winapi import (
        create_process_with_handle_list,
        get_std_handle,
        STD_INPUT_HANDLE,
        STD_OUTPUT_HANDLE,
        STD_ERROR_HANDLE,
    )

    # Resolve standard stream handles
    stdin_h = _resolve_std_handle(stdin)
    stdout_h = _resolve_std_handle(stdout)
    stderr_h = _resolve_std_handle(stderr)

    # Build the complete list of handles the child should see.
    # This includes inherit handles + standard stream handles.
    all_handles = list(handles)

    # Add standard handles that aren't already in the inherit list
    if stdin_h is not None and stdin_h not in all_handles:
        all_handles.append(stdin_h)
    if stdout_h is not None and stdout_h not in all_handles:
        all_handles.append(stdout_h)
    if stderr_h is not None and stderr_h not in all_handles:
        all_handles.append(stderr_h)

    # For handles not explicitly specified, use the current standard handles
    # so the child has valid standard streams
    if stdin_h is None:
        stdin_h = get_std_handle(STD_INPUT_HANDLE)
        if stdin_h not in all_handles and stdin_h != 0:
            all_handles.append(stdin_h)
    if stdout_h is None:
        stdout_h = get_std_handle(STD_OUTPUT_HANDLE)
        if stdout_h not in all_handles and stdout_h != 0:
            all_handles.append(stdout_h)
    if stderr_h is None:
        stderr_h = get_std_handle(STD_ERROR_HANDLE)
        if stderr_h not in all_handles and stderr_h != 0:
            all_handles.append(stderr_h)

    # Remove any zero/invalid handles from the list
    all_handles = [h for h in all_handles if h and h != -1]

    # Handle DEVNULL case
    devnull_path = None
    if stdin is subprocess.DEVNULL or stdout is subprocess.DEVNULL or stderr is subprocess.DEVNULL:
        devnull_path = "NUL"

    # Build command line string
    cmd_line = _build_command_line(command)

    # Get environment
    env = dict(os.environ)

    try:
        process_handle, pid = create_process_with_handle_list(
            cmd_line,
            all_handles,
            env=env,
            stdin_handle=stdin_h if stdin is not subprocess.DEVNULL else None,
            stdout_handle=stdout_h if stdout is not subprocess.DEVNULL else None,
            stderr_handle=stderr_h if stderr is not subprocess.DEVNULL else None,
        )
    except OSError as exc:
        raise WSpawnError(str(exc), kind="os") from exc

    return SpawnedProcess((process_handle, pid), handles)


def _build_command_line(argv):
    """Build a Windows command line string from a list of arguments.

    Uses proper quoting rules for Windows command lines.
    """
    parts = []
    for arg in argv:
        if not arg:
            parts.append('""')
            continue
        # Check if quoting is needed
        needs_quoting = False
        has_backslash = False
        for ch in arg:
            if ch in (' ', '\t', '"'):
                needs_quoting = True
                break
            if ch == '\\':
                has_backslash = True

        if not needs_quoting and not has_backslash:
            parts.append(arg)
        else:
            # Use subprocess.list2cmdline-style quoting
            result = '"'
            num_backslashes = 0
            for ch in arg:
                if ch == '\\':
                    num_backslashes += 1
                elif ch == '"':
                    result += '\\' * (num_backslashes * 2 + 1)
                    result += ch
                    num_backslashes = 0
                else:
                    result += '\\' * num_backslashes
                    result += ch
                    num_backslashes = 0
            result += '\\' * (num_backslashes * 2)
            result += '"'
            parts.append(result)

    return ' '.join(parts)

