    except TypeError as exc:
        raise WSpawnError(
            "argv must be an iterable of paths: %s" % exc,
            kind="badarg",
        ) from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError(
            "inherit must be a sequence of handles, not a single handle",
            kind="badarg",
        )
    try:
        return tuple(int(item) for item in inherit)
    except (TypeError, ValueError) as exc:
        raise WSpawnError(
            "inherit must contain integer handles: %s" % exc,
            kind="badarg",
        ) from exc


def _get_std_handle_value(spec):
    """Convert a stdin/stdout/stderr specification to a Windows HANDLE value.

    Returns None if the spec means "use default".
    Returns 'DEVNULL' sentinel for subprocess.DEVNULL.
    """
    if spec is None:
        return None
    if spec is subprocess.DEVNULL:
        return "DEVNULL"
    if isinstance(spec, int):
        return spec
    try:
        fd = spec.fileno()
    except (AttributeError, OSError):
        raise WSpawnError(
            "stdin/stdout/stderr must be None, DEVNULL, an int, or a file object",
            kind="badarg",
        )
    if os.name == "nt":
        import msvcrt
        return msvcrt.get_osfhandle(fd)
    return fd


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The child process will only be able to access the handles listed in
    ``inherit``, plus any explicitly specified standard streams.  All other
    handles from the parent are invisible to the child.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    if os.name != "nt":
        raise WSpawnError(
            "spawn requires Windows",
            kind="unsupported",
        )

    from ._winapi import (
        HANDLE_FLAG_INHERIT,
        get_handle_information,
        set_handle_information,
    )
    from .inherit import inheritable_handles

    # Resolve standard stream specifications
    stdin_v = _get_std_handle_value(stdin)
    stdout_v = _get_std_handle_value(stdout)
    stderr_v = _get_std_handle_value(stderr)

    # Collect all handles that should be visible to the child
    wanted = set(handles)

    # Add standard stream handles if they are real handles (not None/DEVNULL)
    for v in (stdin_v, stdout_v, stderr_v):
        if isinstance(v, int):
            wanted.add(v)

    # Build the Popen kwargs for standard streams
    popen_kwargs = {"close_fds": False}

    if stdin is not None:
        popen_kwargs["stdin"] = stdin
    if stdout is not None:
        popen_kwargs["stdout"] = stdout
    if stderr is not None:
        popen_kwargs["stderr"] = stderr

    # Strategy: temporarily adjust inheritance flags so that only the wanted
    # handles are inheritable when the child is created.
    #
    # 1. Find all currently-inheritable handles.
    # 2. Make the wanted handles inheritable.
    # 3. Make everything else non-inheritable.
    # 4. Create the child process (bInheritHandles=TRUE via close_fds=False).
    # 5. Restore the original inheritance state.

    # Step 1: snapshot current inheritable handles
    try:
        current_inheritable = set(inheritable_handles())
    except Exception:
        current_inheritable = set()

    # Also include handles that the caller wants but might not be in the
    # enumeration (e.g., because they were just created)
    to_make_inheritable = set()
    to_make_non_inheritable = set()

    # Handles we need to make inheritable for the child
    for h in wanted:
        ok, flags = get_handle_information(h)
        if ok and not (flags & HANDLE_FLAG_INHERIT):
            to_make_inheritable.add(h)

    # Handles we need to temporarily make non-inheritable
    for h in current_inheritable:
        if h not in wanted:
            to_make_non_inheritable.add(h)

    # Step 2 & 3: adjust flags
    changed_to_inheritable = []
    changed_to_non_inheritable = []

    try:
        for h in to_make_inheritable:
            ok, err = set_handle_information(h, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT)
            if ok:
                changed_to_inheritable.append(h)

        for h in to_make_non_inheritable:
            ok, err = set_handle_information(h, HANDLE_FLAG_INHERIT, 0)
            if ok:
                changed_to_non_inheritable.append(h)

        # Step 4: create the child
        try:
            popen = subprocess.Popen(command, **popen_kwargs)
        except OSError as exc:
            raise WSpawnError(str(exc), kind="os") from exc

    finally:
        # Step 5: restore original state
        for h in changed_to_inheritable:
            set_handle_information(h, HANDLE_FLAG_INHERIT, 0)
        for h in changed_to_non_inheritable:
            set_handle_information(h, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT)

    return SpawnedProcess(popen, handles)
